S={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
T={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
# D4 on 9x10 rectangle, output coords with dimensions adjusted; include flips and rotations based on rectangular bounds.
transforms={
'id':lambda r,c:(r,c),
'flipH':lambda r,c:(r,9-c),
'flipV':lambda r,c:(8-r,c),
'rot180':lambda r,c:(8-r,9-c),
'T':lambda r,c:(c,r),
'rot90cw':lambda r,c:(c,8-r),
'rot90ccw':lambda r,c:(9-c,r),
'antiT':lambda r,c:(9-c,8-r)
}
for n,f in transforms.items():
 A={f(r,c) for r,c in S}
 print(n,len(A), 'match',A==T, 'intersection',len(A&T), 'bbox', (min(r for r,c in A),max(r for r,c in A),min(c for r,c in A),max(c for r,c in A)))
